def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    retaliations = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            retaliations += 1
            if retaliations >= 2:
                return 'C'
    if n == 5:
        return 'D'
    if 20 <= n <= 92 and (n - 20) % 8 == 0:
        return 'D'
    return 'C'
